}

/* ── Accessibility: skip link ─────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #0f1117;
  font-weight: 700;
  border-radius: 0 0 var(--radius) var(--radius);
  text-decoration: none;
  z-index: 100;
}
.skip-link:focus {
  top: 0;
}

/* ── Page layout ──────────────────────────────────────── */
body {
  font-family: system-ui, -apple-system, "Segoe UI", Helvetica, Arial, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--bg);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
}

header {
  text-align: center;
  padding: 3.5rem 1.5rem 2rem;
  background: linear-gradient(180deg, #16192680 0%, transparent 100%);
  border-bottom: 1px solid var(--border);
}

header h1 {
  font-size: clamp(1.75rem, 5vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #c7caff 0%, var(--accent) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

header p {
  margin-top: 0.5rem;
  color: var(--text-muted);
  font-size: 1.05rem;
}

main {
  flex: 1;
  width: min(720px, 100% - 3rem);
  margin: 2.5rem auto;
  display: flex;
  flex-direction: column;
  gap: 0.875rem;
}

footer {
  text-align: center;
  padding: 1.5rem;
  color: var(--text-muted);
  font-size: 0.85rem;
  border-top: 1px solid var(--border);
}

/* ── Disclosure: outer wrapper ────────────────────────── */
.example {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.example:has(button[aria-expanded="true"]) {
  border-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent-glow), 0 4px 24px #0007;
}

/* ── Disclosure: trigger ──────────────────────────────── */
.example h2 {
  /* neutralise heading margins */
  margin: 0;
}

.example h2 button {
  all: unset;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  padding: 1.1rem 1.4rem;
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
  cursor: pointer;
  transition: background var(--transition), color var(--transition);
}

.example h2 button::after {
  content: "";
  display: block;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
  background-color: var(--accent);
  /* chevron via clip-path — no extra element needed */
  clip-path: polygon(20% 35%, 50% 65%, 80% 35%, 87% 42%, 50% 75%, 13% 42%);
  transition: transform var(--transition);
}

.example h2 button[aria-expanded="true"]::after {
  transform: rotate(180deg);
}

.example h2 button:hover {
  background: var(--surface-hover);
  color: #fff;
}

/* ── Visible focus ring (keyboard-only) ───────────────── */
.example h2 button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
  border-radius: var(--radius);
}

/* ── Disclosure: panel ────────────────────────────────── */
.details {
  padding: 0 1.4rem 1.2rem;
  color: var(--text-muted);
  border-top: 1px solid var(--border);
}

.details p {
  margin-top: 0.9rem;
}

/* ── Reduced motion ───────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ── Forced colors (Windows High Contrast) ────────────── */
@media (forced-colors: active) {
  .example {
    border: 1px solid ButtonText;
  }
  .example h2 button::after {
    background-color: ButtonText;
  }
  .example h2 button:focus-visible {
    outline: 3px solid Highlight;
  }
}

/* ── Reflow: narrow viewports (320 px) ────────────────── */
@media (max-width: 360px) {
  header {
    padding: 2rem 1rem 1.25rem;
  }
  .example h2 button {
    padding: 0.9rem 1rem;
    font-size: 0.95rem;
  }
  .details {
    padding: 0 1rem 1rem;
  }
}
